import React from "react";
import { FaSlidersH } from "react-icons/fa";

class HistoryTableRow extends React.Component {
  constructor(props) {
    super(props);
    this.handleDetailsClick = this.handleDetailsClick.bind(this);
  }

  handleDetailsClick() {
    const { record, onDetails } = this.props;

    if (onDetails) {
      onDetails(record.id);
    }
  }

  render() {
    const { record } = this.props;

    const status = record.status || {
      text: "نامشخص",
      color: "#6c757d",
    };

    return (
      <div
        className="history-grid py-3 border-bottom"
        style={{
          display: "grid",
          gridTemplateColumns: "1fr 1.3fr 1fr 0.8fr",
          alignItems: "center",
        }}
      >
        <span className="text-center small text-dark">
          {record.deviceType}
        </span>

        <span className="text-center small text-dark">
          {record.issue}
        </span>

        <span className="text-center small text-muted">
          {record.date}
        </span>

        <div
          className="d-flex align-items-center justify-content-center gap-2"
          style={{
            cursor: "pointer",
          }}
          onClick={this.handleDetailsClick}
          title={status.text}
        >
          <span
            className="rounded-circle"
            style={{
              width: 16,
              height: 16,
              minWidth: 16,
              backgroundColor: status.color,
              transition:
                "background-color 0.2s ease",
            }}
          />

          <FaSlidersH
            className="text-secondary"
            size={14}
            style={{
              transform: "rotate(90deg)",
            }}
          />
        </div>
      </div>
    );
  }
}

export default HistoryTableRow;
